1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioOutput {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	const CURSE_SURCHARGE_RATE = 0.5;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
60	const LOYALTY_THRESHOLD_YEARS = 2;
61	const LOYALTY_DISCOUNT_RATE = 0.2;
62	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
63	const DEDUCTIBLE_PER_DAMAGE = 100;
64	const CAP_MULTIPLIER = 2;
65	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
66	const HALF_REIMBURSEMENT_RATE = 0.5;
67	
68	// The price list: one row per insurable item type. The two numbers are
69	// independent columns — the premium is what the customer pays to insure the
70	// item, the insured value is what the MHPCO would owe for it.
71	interface ItemSpec {
72	  basePremium: number;
73	  insuredValue: number;
74	}
75	
76	const ITEM_SPECS: Record<string, ItemSpec> = {
77	  sword: { basePremium: 100, insuredValue: 1000 },
78	  amulet: { basePremium: 60, insuredValue: 600 },
79	  staff: { basePremium: 80, insuredValue: 800 },
80	  potion: { basePremium: 40, insuredValue: 400 },
81	  rune: { basePremium: 25, insuredValue: 250 },
82	  moonstone: { basePremium: 25, insuredValue: 250 },
83	};
84	
85	const BLOCK_SIZE = 3;
86	const BLOCK_BASE_PREMIUM = 60;
87	
88	// Tallies a collection into "key → how many". Both the premium path (items by
89	// item type) and the claim path (damages by damaged type) ask this same
90	// question, they just reach for the key in a different field.
91	const countBy = <T>(values: T[], keyOf: (value: T) => string): Map<string, number> => {
92	  const counts = new Map<string, number>();
93	  for (const value of values) {
94	    const key = keyOf(value);
95	    counts.set(key, (counts.get(key) ?? 0) + 1);
96	  }
97	  return counts;
98	};
99	
100	const countItemsByType = (items: Item[]): Map<string, number> =>
101	  countBy(items, (item) => item.type);
102	
103	const countDamagesByType = (damages: Damage[]): Map<string, number> =>
104	  countBy(damages, (damage) => damage.itemType);
105	
106	// The single point where an item type is resolved. Every price lookup goes
107	// through here, so an unknown type cannot slip into any calculation.
108	const specOfType = (type: string): ItemSpec => {
109	  const spec = ITEM_SPECS[type];
110	  if (spec === undefined) {
111	    throw new Error(`unknown item type: ${type}`);
112	  }
113	  return spec;
114	};
115	
116	const basePremiumOfType = (type: string): number => specOfType(type).basePremium;
117	
118	const insuredValueOfType = (type: string): number => specOfType(type).insuredValue;
119	
120	const basePremiumOfAlikeItems = (type: string, count: number): number =>
121	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOfType(type);
122	
123	const policyBasePremium = (items: Item[]): number =>
124	  [...countItemsByType(items)].reduce(
125	    (total, [type, count]) => total + basePremiumOfAlikeItems(type, count),
126	    0,
127	  );
128	
129	const firstInsuranceSurcharge = (policyBase: number): number =>
130	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
131	
132	const itemBasePremium = (item: Item): number => basePremiumOfType(item.type);
133	
134	const isCursed = (item: Item): boolean => item.cursed === true;
135	
136	const isHighlyEnchanted = (item: Item): boolean =>
137	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
138	
139	const curseSurcharge = (item: Item): number =>
140	  isCursed(item) ? itemBasePremium(item) * CURSE_SURCHARGE_RATE : 0;
141	
142	const highEnchantmentSurcharge = (item: Item): number =>
143	  isHighlyEnchanted(item)
144	    ? itemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
145	    : 0;
146	
147	const itemSurchargeTotal = (items: Item[]): number =>
148	  items.reduce(
149	    (total, item) => total + curseSurcharge(item) + highEnchantmentSurcharge(item),
150	    0,
151	  );
152	
153	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
154	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
155	    ? policyBase * LOYALTY_DISCOUNT_RATE
156	    : 0;
157	
158	const followUpContractDiscount = (policyBase: number, previousQuotes: number): number =>
159	  previousQuotes > 0 ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0;
160	
161	const policyWideAdjustments = (
162	  policyBase: number,
163	  customer: Customer,
164	  previousQuotes: number,
165	): number =>
166	  firstInsuranceSurcharge(policyBase) -
167	  loyaltyDiscount(policyBase, customer) -
168	  followUpContractDiscount(policyBase, previousQuotes);
169	
170	const quote = (
171	  step: QuoteStep,
172	  customer: Customer,
173	  previousQuotes: number,
174	): QuoteResult => {
175	  const policyBase = policyBasePremium(step.items);
176	  const premiumBeforeRounding =
177	    policyBase +
178	    itemSurchargeTotal(step.items) +
179	    policyWideAdjustments(policyBase, customer, previousQuotes) +
180	    PROCESSING_FEE;
181	  return { premium: Math.ceil(premiumBeforeRounding) };
182	};
183	
184	interface Policy {
185	  items: Item[];
186	  remainingCap: number;
187	}
188	
189	const insuranceSum = (items: Item[]): number =>
190	  items.reduce((total, item) => total + insuredValueOfType(item.type), 0);
191	
192	const isHalfCovered = (item: Item): boolean =>
193	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
194	
195	// How much of the damage the policy covers, before the deductible is taken off.
196	const coveredAmount = (damage: Damage, item: Item): number =>
197	  isHalfCovered(item) ? damage.amount * HALF_REIMBURSEMENT_RATE : damage.amount;
198	
199	const payoutForDamage = (damage: Damage, item: Item): number =>
200	  Math.max(0, coveredAmount(damage, item) - DEDUCTIBLE_PER_DAMAGE);
201	
202	const damagedItem = (policy: Policy, damage: Damage): Item => {
203	  const item = policy.items.find((insured) => insured.type === damage.itemType);
204	  if (item === undefined) {
205	    throw new Error(`damaged item is not covered by the policy: ${damage.itemType}`);
206	  }
207	  return item;
208	};
209	
210	// Every reason an incident can be rejected lives here, so the pricing functions
211	// below can assume they are working on a valid incident. Throws on the first
212	// problem found; nothing has been paid out or decremented at this point.
213	// Returns each damage paired with the insured item it resolved to, so the
214	// pricing pass does not have to look the items up a second time.
215	const validateIncident = (
216	  incident: Incident,
217	  policy: Policy,
218	): { damage: Damage; item: Item }[] => {
219	  const insuredCounts = countItemsByType(policy.items);
220	  for (const [type, damaged] of countDamagesByType(incident.damages)) {
221	    const insured = insuredCounts.get(type);
222	    // An entirely uninsured type is reported by damagedItem below, which gives
223	    // a clearer message than an over-count would.
224	    if (insured !== undefined && damaged > insured) {
225	      throw new Error(`more damages than insured items: ${type}`);
226	    }
227	  }
228	
229	  return incident.damages.map((damage) => {
230	    if (damage.amount < 0) {
231	      throw new Error(`negative damage amount: ${damage.amount}`);
232	    }
233	    return { damage, item: damagedItem(policy, damage) };
234	  });
235	};
236	
237	// A claim is all-or-nothing: the whole incident is validated before any pricing
238	// happens and before the cap is touched, so a claim that turns out to be
239	// invalid cannot leave a partial decrement behind for later steps to inherit.
240	const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
241	  const desiredPayout = validateIncident(step.incident, policy)
242	    .map(({ damage, item }) => payoutForDamage(damage, item))
243	    .reduce((total, amount) => total + amount, 0);
244	
245	  // Intermediate amounts stay fractional; the payout is rounded once here, down
246	  // in the MHPCO's favor, and that same figure is what the cap is charged.
247	  const payout = Math.floor(Math.min(desiredPayout, policy.remainingCap));
248	  policy.remainingCap -= payout;
249	  return { payout, remainingCap: policy.remainingCap };
250	};
251	
252	const policyFor = (items: Item[]): Policy => ({
253	  items,
254	  remainingCap: insuranceSum(items) * CAP_MULTIPLIER,
255	});
256	
257	const countQuotesBefore = (steps: Step[], stepIndex: number): number =>
258	  steps.slice(0, stepIndex).filter((step) => step.op === "quote").length;
259	
260	export const runScenario = (scenario: Scenario): ScenarioOutput => {
261	  // A policy is registered under the index of the step that quoted it; that
262	  // step index is the id later claim steps refer to. Claims mutate their
263	  // policy's remainingCap, so the register carries state across steps.
264	  const policies = new Map<number, Policy>();
265	
266	  const results = scenario.steps.map((step, stepIndex): StepResult => {
267	    if (step.op === "claim") {
268	      return claim(step, policies.get(step.policy)!);
269	    }
270	    policies.set(stepIndex, policyFor(step.items));
271	    return quote(
272	      step,
273	      scenario.customer,
274	      countQuotesBefore(scenario.steps, stepIndex),
275	    );
276	  });
277	
278	  return { results };
279	};
